:root{
  --accent:#4B3BFF;
  --accent-soft:rgba(75,59,255,0.1);
  --accent-ink:#FFFFFF;
  --radius:14px;
  --bg:#FBFAF8;
  --text:#16161A;
  --muted:#6E6E78;
  --border:#E9E7E2;
  --shadow:0 1px 2px rgba(0,0,0,0.08);
}
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:-apple-system,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;background:var(--bg);color:var(--text);line-height:1.6}
.container{max-width:880px;margin:auto;padding:0 16px}
.title{font-weight:650;margin:24px 0 16px}
.form{display:flex;flex-wrap:wrap;gap:8px}
.form-row{flex:1 1 200px;display:flex;flex-direction:column}
.form-row label{font-size:14px;margin-bottom:4px}
.form-row input{padding:8px;border:1px solid var(--border);border-radius:var(--radius);font-size:15px}
.form-row input:focus{outline:none;border-color:var(--accent);box-shadow:0 0 0 3px var(--accent-soft)}
.btn{padding:10px 16px;border-radius:var(--radius);font-size:15px;cursor:pointer}
.btn.primary{background:var(--accent);color:var(--accent-ink);border:none}
.btn.primary:hover{opacity:.9}
.btn.secondary{background:none;border:1px solid var(--accent);color:var(--accent)}
.btn.secondary:hover{background:var(--accent-soft)}
.entries, .chart{margin-top:32px}
.entries h2, .chart h2{font-weight:650;margin-bottom:12px}
#entry-list{list-style:none}
.entry-item{display:flex;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border)}
.entry-item:last-child{border-bottom:none}
.entry-amount{font-variant-numeric:tabular-nums}
@media (max-width:560px){
  .form{flex-direction:column}
  .btn{width:100%}
  .title{font-size:24px}
}

// 数据结构：{id, amount, category, remark, timestamp}
const STORAGE_KEY = 'nucleus:smallbook';
const form = document.getElementById('entry-form');
const listEl = document.getElementById('entry-list');
const chartCanvas = document.getElementById('pie-chart');
let chart;

// 防 XSS 转义
function escapeHTML(str) {
  return String(str).replace(/[&<>"']/g, function (c) {
    return {
      '&': '&amp;',
      '<': '&lt;',
      '>': '&gt;',
      '"': '&quot;',
      "'": '&#39;'
    }[c];
  });
}

// 本地存储
function loadData() {
  return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
}
function saveData(data) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(data));
}

// 渲染列表
function renderList() {
  const data = loadData();
  listEl.innerHTML = '';
  if (data.length === 0) {
    const li = document.createElement('li');
    li.textContent = '暂无账单，快来添加吧！';
    li.style.padding = '8px 0';
    listEl.appendChild(li);
    return;
  }
  data.forEach(item => {
    const li = document.createElement('li');
    li.className = 'entry-item';
    li.innerHTML = `<span>${escapeHTML(item.category)}</span><span class="entry-amount">${item.amount.toFixed(2)}</span>`;
    listEl.appendChild(li);
  });
}

// 渲染图表
function renderChart() {
  const data = loadData();
  const totals = {};
  data.forEach(i => {
    totals[i.category] = (totals[i.category] || 0) + i.amount;
  });
  const labels = Object.keys(totals);
  const values = labels.map(l => totals[l]);

  if (!chartCanvas) return;

  // 若 Chart 已加载
  if (typeof Chart !== 'undefined') {
    if (chart) chart.destroy();
    chart = new Chart(chartCanvas, {
      type: 'pie',
      data: {
        labels,
        datasets: [{
          data: values,
          backgroundColor: labels.map(() => 'var(--accent)')
        }]
      },
      options: {
        responsive: true,
        plugins: {
          legend: { position: 'bottom' }
        }
      }
    });
  }
}

// 载入 Chart.js CDN
function loadChartLib(callback) {
  if (typeof Chart !== 'undefined') {
    callback();
    return;
  }
  const script = document.createElement('script');
  script.src = 'https://cdn.jsdelivr.net/npm/chart.js@4.4.0/dist/chart.umd.min.js';
  script.onload = callback;
  script.onerror = () => {
    console.error('Chart.js 加载失败');
  };
  document.head.appendChild(script);
}

// 表单提交
form.addEventListener('submit', e => {
  e.preventDefault();
  const amount = parseFloat(form.amount.value);
  const category = form.category.value.trim();
  const remark = form.remark.value.trim();
  if (isNaN(amount) || !category) {
    alert('请填写金额和分类');
    return;
  }
  const entry = {
    id: Date.now(),
    amount,
    category,
    remark,
    timestamp: Date.now()
  };
  const data = [...loadData(), entry];
  saveData(data);
  renderList();
  renderChart();
  form.reset();
});

// 初始化
document.addEventListener('DOMContentLoaded', () => {
  renderList();
  loadChartLib(() => {
    renderChart();
  });
});
